// Unified course data API.
// All JSON files are named {series}-{unit}.json (generated by scripts/convert.py).
// Use getUnit / getLesson / allWords throughout the app — never import JSON directly.

import { COURSE_REGISTRY } from "./courses.js";

// Eagerly import all known data files.
// When adding a new course, run `npm run convert` then add its imports here.
import hsk1 from "./hsk-1.json";
import hsk2 from "./hsk-2.json";
import hsk3 from "./hsk-3.json";
import hsk4 from "./hsk-4.json";
import hsk5 from "./hsk-5.json";
import hsk6 from "./hsk-6.json";
import newhsk3_1 from "./newhsk3-1.json";
import newhsk3_2 from "./newhsk3-2.json";
import newhsk3_3 from "./newhsk3-3.json";
import huihua360_1 from "./huihua360-1.json";
import huihua360_2 from "./huihua360-2.json";
import huihua360_3 from "./huihua360-3.json";
import huihua360_4 from "./huihua360-4.json";

const DATASETS = {
  "hsk-1": hsk1,
  "hsk-2": hsk2,
  "hsk-3": hsk3,
  "hsk-4": hsk4,
  "hsk-5": hsk5,
  "hsk-6": hsk6,
  "newhsk3-1": newhsk3_1,
  "newhsk3-2": newhsk3_2,
  "newhsk3-3": newhsk3_3,
  "huihua360-1": huihua360_1,
  "huihua360-2": huihua360_2,
  "huihua360-3": huihua360_3,
  "huihua360-4": huihua360_4,
};

function key(seriesId, unitId) {
  return `${seriesId}-${unitId}`;
}

function countWords(ds) {
  return ds.lessons.reduce((n, l) => n + l.words.length, 0);
}

// All series with per-unit metadata (lesson count, word count, availability).
// Used by HomeView to render the course grid without loading full data.
export const courseRegistry = COURSE_REGISTRY.map((series) => ({
  ...series,
  units: series.units.map((unit) => {
    const ds = DATASETS[key(series.id, unit.id)];
    return {
      ...unit,
      available: unit.available && !!ds,
      lessonCount: ds ? ds.lessons.length : 0,
      wordCount: ds ? countWords(ds) : 0,
    };
  }),
}));

export function getUnit(seriesId, unitId) {
  return DATASETS[key(seriesId, unitId)] || null;
}

export function getLesson(seriesId, unitId, lessonNum) {
  const ds = getUnit(seriesId, unitId);
  if (!ds) return null;
  return ds.lessons.find((l) => l.num === Number(lessonNum)) || null;
}

export function allWords(seriesId, unitId) {
  const ds = getUnit(seriesId, unitId);
  if (!ds) return [];
  return ds.lessons.flatMap((l) => l.words);
}

// Flat index of every word across all courses, each tagged with its source
// (series / unit / lesson). Built once on first search, then cached.
let _flatIndex = null;
function buildFlatIndex() {
  const out = [];
  for (const series of COURSE_REGISTRY) {
    for (const unit of series.units) {
      const ds = DATASETS[key(series.id, unit.id)];
      if (!ds) continue;
      for (const lesson of ds.lessons) {
        for (const word of lesson.words) {
          out.push({
            word,
            series: series.id,
            seriesName: series.name,
            unit: unit.id,
            unitLabel: unit.label,
            lessonNum: lesson.num,
            lessonTitle: lesson.title,
          });
        }
      }
    }
  }
  return out;
}

// Strip pinyin tone marks so "qishi" matches "qǐshì" (and lowercases).
function normalize(s) {
  return (s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

// Also drop whitespace \u2014 pinyin in the data is inconsistently spaced
// ("n\u01d0 h\u01ceo" vs "n\u01d0h\u01ceo"), so match space-insensitively.
function normalizePinyin(s) {
  return normalize(s).replace(/\s+/g, "");
}

// Does a word match a query? Matches hanzi (raw), pinyin (tone- and
// space-insensitive), or English meaning. Empty query matches everything.
// Shared by global search and the in-lesson search box.
export function matchWord(word, query) {
  const raw = (query || "").trim();
  if (!raw) return true;
  return (
    word.hanzi.includes(raw) ||
    normalizePinyin(word.pinyin).includes(normalizePinyin(raw)) ||
    normalize(word.meaning).includes(normalize(raw))
  );
}

// Global cross-course search over hanzi / pinyin / English meaning.
// Returns { total, results } where results is capped at `limit` entries.
export function searchAll(query, limit = 60) {
  const raw = query.trim();
  if (!raw) return { total: 0, results: [] };
  if (!_flatIndex) _flatIndex = buildFlatIndex();
  const matches = _flatIndex.filter((e) => matchWord(e.word, raw));
  return { total: matches.length, results: matches.slice(0, limit) };
}
